function MandateModal({existing,busy,onClose,onSave}:{existing:Mandate|null;busy:boolean;onClose:()=>void;onSave:(v:CreateMandate)=>void}){
 const [title,setTitle]=useState(existing?.title??referenceTitle),[text,setText]=useState(existing?.thesis_text??mandateStarter),[count,setCount]=useState(existing?.target_count??2),[reference,setReference]=useState(existing?.reference_status??'user_supplied'),[starter,setStarter]=useState('reference');
 function submit(e:FormEvent){e.preventDefault();onSave({title:title.trim(),thesis_text:text,target_count:count,reference_status:reference})}
 return <Modal title={existing?'Revise saved run brief':'Create a sourcing mandate'} onClose={onClose}><form className="modal-body" onSubmit={submit}><div className="gap-box"><strong>{existing?`Saved thesis v${existing.thesis_version} · ${label(existing.reference_status)}`:'Human-reviewed reference v0.3 · editable abridgment'}</strong><p>{existing?'Changes save as a separate mandate. This preserves the original mandate, cases, and assessments.':'Hypothetical YC scouting; independently drafted and not endorsed. This abridgment preserves the four proof tracks. Saving text does not activate runtime policy or imply human qualification.'}</p></div>{!existing&&<label>Starting text<select value={starter} onChange={e=>{const v=e.target.value;setStarter(v);setTitle(v==='reference'?referenceTitle:v==='fixture'?'Legacy harness · illustrative mandate':'');setText(v==='reference'?mandateStarter:v==='fixture'?placeholder:'');setReference(v==='fixture'?'placeholder':'user_supplied')}}><option value="reference">Reviewed reference v0.3 · abridged</option><option value="fixture">Legacy synthetic harness placeholder</option><option value="custom">Write my own mandate</option></select></label>}<label>Mandate name<input required maxLength={200} value={title} onChange={e=>setTitle(e.target.value)}/></label><label>Saved run brief text<textarea required rows={8} maxLength={20000} value={text} onChange={e=>setText(e.target.value)}/></label><div className="form-columns"><label>Run target · operator choice<input required type="number" min="1" max="100" value={count} onChange={e=>setCount(Number(e.target.value))}/></label><label>Reference status<select value={reference} onChange={e=>setReference(e.target.value as 'placeholder'|'user_supplied')}><option value="placeholder">Placeholder · illustrative only</option><option value="user_supplied">User supplied · reviewed text</option></select></label></div><p className="tiny muted">The default target of 2 is a demo run choice, not a target set by v0.3. The current app counts saved outreach_ready states; human qualification approval is required for semantic cases; extra draft approval before counting remains a separate choice. Saving retains your text exactly and does not approve inferred criteria or perform semantic matching.</p><div className="modal-actions"><button type="button" className="secondary" disabled={busy} onClick={onClose}>Cancel</button><button className="primary" disabled={busy||!text.trim()||!title.trim()}>{busy?<Loader2 size={16} className="spin"/>:<Check size={16}/>} {existing?'Save as new mandate':'Save mandate'}</button></div></form></Modal>
}
function SettingsModal({mode,url,config,onClose,onSave}:{mode:TransportMode;url:string;config:ConfigStatus|null;onClose:()=>void;onSave:(mode:TransportMode,url:string)=>void}){
 const [next,setNext]=useState(mode),[base,setBase]=useState(url);
 return <Modal title="Connection & data boundaries" onClose={onClose}><form className="modal-body" onSubmit={e=>{e.preventDefault();onSave(next,base.replace(/\/$/,''))}}><label>Frontend transport<select value={next} onChange={e=>setNext(e.target.value as TransportMode)}><option value="http">HTTP backend · default integration</option><option value="fixture">Browser fixtures · synthetic fallback</option></select></label><label>Backend base URL<input type="url" required value={base} onChange={e=>setBase(e.target.value)}/></label><p className="tiny muted">Use the backend origin without /api/v1. A failed HTTP request always shows an error. Switching transport selects a separate data store.</p><div className="config-grid"><span>Provider mode</span><strong>{config?.provider_mode??'Unknown'}</strong><span>Crustdata credential present</span><strong>{config?config.crustdata_configured?'Yes':'No':'Unknown'}</strong><span>Backend reference status</span><strong>{config?label(config.thesis_status):'Unknown'}</strong><span>Semantic evaluator</span><strong>{config?config.semantic_matcher_configured?'Configured · execution requires a saved result':'Not configured':'Unknown'}</strong></div>{next==='fixture'&&<div className="gap-box">Explicit fallback: all browser fixture companies, people, assessments, and signals are synthetic. Data is stored only in this browser; no provider request is made.</div>}<div className="modal-actions"><button type="button" className="secondary" onClick={onClose}>Cancel</button><button className="primary">Apply connection</button></div></form></Modal>
}
function ReplayModal({company,busy,templates,templateError,onClose,onSave}:{company:string;busy:boolean;templates:ReplayTemplate[];templateError:string;onClose:()=>void;onSave:(s:SignalInput)=>void}){
 const [summary,setSummary]=useState(`Synthetic demo replay: ${company} reports a first customer deployment. This illustrative claim has not been independently verified.`);
 return <Modal title="Replay a material signal" onClose={onClose}><form className="modal-body" onSubmit={e=>{e.preventDefault();onSave({summary,claim_type:'customer_deployment',source_url:null,replayed:true,data_mode:'synthetic'})}}><div className="row wrap"><Badge value="replayed"/><Provenance mode="synthetic"/><Badge value="fixture"/></div><p>This saves a labeled synthetic signal and requests a new assessment from the selected evaluator. The earlier assessment remains in the case history.</p>{templateError&&<div className="gap-box">Catalog replay helper unavailable: {templateError}</div>}{templates.map((t,i)=><div className="catalog-replay" key={i}><strong>{t.label}</strong><p>{t.signal.summary}</p><button type="button" className="primary" disabled={busy} onClick={()=>onSave(t.signal)}><Radio size={15}/>Replay catalog milestone</button><p className="tiny muted">Exact backend fixture scenario. Predefined outcome; not semantic reasoning.</p></div>)}<label>Custom unverified signal summary<textarea rows={5} required maxLength={5000} value={summary} onChange={e=>setSummary(e.target.value)}/></label><div className="gap-box">A replay is not verified live evidence. The resulting disposition may still require investigation. The foundation evaluator is a labeled development harness.</div><div className="modal-actions"><button type="button" className="secondary" disabled={busy} onClick={onClose}>Cancel</button><button className="primary" disabled={busy||!summary.trim()}>{busy?<Loader2 className="spin" size={16}/>:<Radio size={16}/>}Save synthetic replay</button></div></form></Modal>
}

